"""Matroska header probe over generated bytes. No real media; nothing here touches the disk."""
import json
import random
import time
import unittest

import mkvgen
from kura import mkvprobe
from kura.mkvprobe import parse_settings, probe

MIB = 1 << 20


class Source:
    """A byte source that records every read the probe makes."""

    def __init__(self, data, size=None):
        self.data, self.size, self.reads = bytes(data), len(data) if size is None else size, []

    def __call__(self, offset, n):
        self.reads.append((offset, n))
        return self.data[offset:offset + n]

    @property
    def largest(self):
        return max((n for _, n in self.reads), default=0)

    @property
    def total(self):
        return sum(n for _, n in self.reads)


def run(data, **kw):
    src = Source(data)
    return probe(src, src.size, **kw), src


def printable(value):
    """Every string in a probe document is printable and at most 200 characters."""
    if isinstance(value, str):
        return len(value) <= 200 and value.isprintable()
    if isinstance(value, dict):
        return all(printable(k) and printable(v) for k, v in value.items())
    if isinstance(value, list):
        return all(printable(v) for v in value)
    return True


class Encoder(unittest.TestCase):
    def test_x264_settings_in_the_first_frame(self):
        result, src = run(mkvgen.build())
        self.assertEqual(result["status"], "ok")
        self.assertEqual(result["warnings"], [])
        enc = result["encoder"]
        self.assertEqual((enc["library"], enc["version"], enc["where"]), ("x264", "164 r3095 baee400", "first_frame"))
        self.assertEqual(enc["settings"]["crf"], "18.0")
        self.assertEqual(enc["settings"]["deblock"], "1:-1:-1")
        self.assertTrue(printable(result))
        json.dumps(result)

    def test_emulation_prevention_bytes_are_removed_before_parsing(self):
        other = bytes(range(1, 17)) + b"\x00\x00\x01\x00\x00\x00\x00\x02payload"
        messages = [mkvgen.sei_message(5, other)]
        raw = mkvgen.sei_nal("avc", [*messages, mkvgen.encoder_message(mkvgen.X264_TEXT)])
        self.assertIn(b"\x00\x00\x03", raw)                        # the fixture really needs the escape
        result, _ = run(mkvgen.build(extra_messages=messages))
        self.assertEqual(result["encoder"]["library"], "x264")
        self.assertEqual(result["encoder"]["settings"]["crf"], "18.0")
        self.assertEqual(result["warnings"], [])

    def test_x265_settings_in_the_hvcc_array(self):
        result, _ = run(mkvgen.build(codec="hevc", settings=mkvgen.X265_TEXT, sei="private"))
        enc = result["encoder"]
        self.assertEqual((enc["library"], enc["version"], enc["where"]),
                         ("x265", "3.5+1-f0c1022b6", "codec_private"))
        self.assertIs(enc["settings"]["wpp"], True)
        self.assertEqual(enc["settings"]["crf"], "19.0")
        self.assertEqual(result["video"]["bit_depth"], 10)
        self.assertEqual(result["video"]["profile"], "main10")

    def test_x265_settings_in_the_first_frame(self):
        result, _ = run(mkvgen.build(codec="hevc", settings=mkvgen.X265_TEXT, sei="frame"))
        self.assertEqual((result["encoder"]["library"], result["encoder"]["where"]), ("x265", "first_frame"))

    def test_settings_behind_a_huge_attachment_are_found_cheaply(self):
        data = mkvgen.build(attach=[("Kura Sans.ttf", "application/x-truetype-font", 5 * MIB)])
        self.assertGreater(len(data), 5 * MIB)
        result, src = run(data)
        self.assertEqual(result["status"], "ok")
        self.assertEqual(result["encoder"]["library"], "x264")
        self.assertLess(result["bytes_read"], MIB)
        self.assertEqual(result["bytes_read"], sum(len(src.data[o:o + n]) for o, n in src.reads))
        self.assertEqual(result["attachments"], {"count": 1, "fonts": 1, "bytes": 5 * MIB, "names": ["Kura Sans.ttf"]})

    def test_audio_block_first_in_the_cluster_is_ignored(self):
        result, _ = run(mkvgen.build(decoy_audio=True))
        self.assertEqual(result["encoder"]["settings"]["crf"], "18.0")
        self.assertNotIn("DECOY", json.dumps(result))

    def test_video_track_number_is_used_not_the_first_block(self):
        result, _ = run(mkvgen.build(video_number=2, decoy_audio=True))
        self.assertEqual(result["video"]["track"], 2)
        self.assertEqual(result["audio"][0]["track"], 1)
        self.assertEqual(result["encoder"]["settings"]["crf"], "18.0")

    def test_laced_video_block_is_skipped_with_a_warning(self):
        result, _ = run(mkvgen.build(laced_decoy_video=True))
        self.assertIn("laced_block_skipped", result["warnings"])
        self.assertEqual(result["encoder"]["settings"]["crf"], "18.0")
        self.assertNotIn("LACED", json.dumps(result))

    def test_no_sei_gives_null_encoder_and_a_warning(self):
        result, _ = run(mkvgen.build(sei=None))
        self.assertIsNone(result["encoder"])
        self.assertIn("no_encoder_settings", result["warnings"])
        self.assertEqual(result["status"], "ok")
        self.assertEqual(result["video"]["codec"], "h264")

    def test_content_encoded_video_is_not_parsed(self):
        result, _ = run(mkvgen.build(content_encoded=True))
        self.assertIn("content_encoded_video", result["warnings"])
        self.assertIsNone(result["encoder"])

    def test_sei_of_another_encoder_uuid_is_ignored(self):
        other = mkvgen.sei_message(5, bytes(16) + b"not an encoder\0")
        result, _ = run(mkvgen.build(settings=None, extra_messages=[other]))
        self.assertIsNone(result["encoder"])

    def test_parse_settings(self):
        parsed = parse_settings(mkvgen.X264_TEXT)
        self.assertEqual((parsed["library"], parsed["version"]), ("x264", "164 r3095 baee400"))
        self.assertEqual(parsed["options"]["psy_rd"], "1.00:0.00")
        parsed = parse_settings(mkvgen.X265_TEXT.replace(" crf=", " / crf="))
        self.assertEqual(parsed["library"], "x265")
        self.assertEqual(parsed["options"]["crf"], "19.0")
        self.assertIs(parsed["options"]["no-pmode"], True)
        self.assertNotIn("/", parsed["options"])
        self.assertEqual(parse_settings("")["options"], {})
        self.assertEqual(parse_settings("options: =x a=")["options"], {"a": ""})
        huge = parse_settings("x264 - options: " + " ".join(f"k{i}={'v' * 500}" for i in range(2000)))
        self.assertLessEqual(len(huge["options"]), mkvprobe.MAX_OPTIONS)
        self.assertTrue(printable(huge))


class Facts(unittest.TestCase):
    def test_tracks_and_container_facts(self):
        result, _ = run(mkvgen.build(
            audio_codecs=("A_AAC", "A_AC3"),
            subs=(("S_TEXT/ASS", "eng", "Kura Signs"), ("S_TEXT/UTF8", "fil", None), ("S_HDMV/PGS", "jpn", None))))
        self.assertEqual(result["container"], "matroska")
        self.assertEqual((result["muxing_app"], result["writing_app"]), ("Kura Mux 1.0", "Kura Writer 1.0"))
        self.assertEqual(result["duration_s"], 1420.0)
        self.assertEqual([a["codec"] for a in result["audio"]], ["aac", "ac3"])
        self.assertEqual(result["audio"][0], {"track": 2, "codec": "aac", "channels": 2, "sample_rate": 48000,
                                              "lang": "jpn", "default": True})
        self.assertFalse(result["audio"][1]["default"])
        self.assertEqual([s["format"] for s in result["subtitles"]], ["ass", "srt", "pgs"])
        self.assertEqual(result["subtitles"][0]["name"], "Kura Signs")
        self.assertEqual([s["forced"] for s in result["subtitles"]], [False, True, False])
        video = result["video"]
        self.assertEqual((video["track"], video["codec_id"], video["width"], video["height"], video["fps"]),
                         (1, "V_MPEG4/ISO/AVC", 1920, 1080, 23.976))

    def test_webm_doc_type(self):
        result, _ = run(mkvgen.build(doc_type="webm"))
        self.assertEqual(result["container"], "webm")

    def test_bit_depth_prefers_colour_then_codec_config_never_audio(self):
        depth = lambda **kw: run(mkvgen.build(**kw))[0]["video"]["bit_depth"]
        self.assertEqual(depth(colour_bits=10, audio_bit_depth=24), 10)
        self.assertEqual(depth(audio_bit_depth=24), 8)                       # avcC profile 100, audio ignored
        self.assertEqual(depth(codec="hevc", settings=mkvgen.X265_TEXT, hevc_bits=10, audio_bit_depth=24), 10)
        self.assertEqual(depth(codec="hevc", settings=mkvgen.X265_TEXT, hevc_bits=12), 12)
        self.assertEqual(depth(avc_profile=110), 10)
        self.assertEqual(depth(avc_profile=100, avc_bit_depth=10), 10)       # avcC extension wins
        self.assertEqual(depth(avc_profile=77), 8)
        self.assertIsNone(depth(avc_profile=244))                            # unknown without the extension
        self.assertEqual(depth(avc_profile=244, avc_bit_depth=8), 8)
        self.assertEqual(depth(avc_profile=110, colour_bits=8), 8)

    def test_profile_names(self):
        self.assertEqual(run(mkvgen.build(avc_profile=110))[0]["video"]["profile"], "high10")

    def test_bitrate_from_tags_else_size_over_duration(self):
        tagged = mkvgen.build(tag_values={1001: {"BPS": "4500000"}, 2000: {"BPS": "192000"}})
        video = run(tagged)[0]["video"]
        self.assertEqual((video["bitrate_kbps"], video["bitrate_source"]), (4500, "tags"))
        plain = mkvgen.build(attach=[("a.ttf", "font/ttf", 1_000_000)])
        result, _ = run(plain)
        self.assertEqual(result["video"]["bitrate_source"], "size_over_duration")
        self.assertEqual(result["video"]["bitrate_kbps"], round(len(plain) * 8 / 1420.0 / 1000))
        junk = run(mkvgen.build(tag_values={1001: {"BPS": "²"}}))[0]["video"]       # isdigit() but not a number
        self.assertEqual(junk["bitrate_source"], "size_over_duration")

    def test_duration_and_fps_fall_back_to_tags(self):
        data = mkvgen.build(duration=None, default_duration=0,
                            tag_values={1001: {"DURATION-eng": "00:23:40.500000000", "NUMBER_OF_FRAMES": "34044"}})
        result, _ = run(data)
        self.assertEqual(result["duration_s"], 1420.5)
        self.assertAlmostEqual(result["video"]["fps"], 23.966, places=2)

    def test_chapters_and_attachments(self):
        fonts = [("A.ttf", "application/octet-stream", 10), ("b.bin", "application/x-truetype-font", 10),
                 ("c.OTF", "font/otf", 10), ("notes.txt", "text/plain", 10)]
        result, _ = run(mkvgen.build(attach=fonts, chapter_atoms=7))
        self.assertEqual(result["attachments"]["count"], 4)
        self.assertEqual(result["attachments"]["fonts"], 3)                  # by mime and by extension
        self.assertEqual(result["attachments"]["names"], [f[0] for f in fonts])
        self.assertEqual(result["attachments"]["bytes"], 40)
        self.assertEqual(result["chapters"], {"present": True, "count": 7})

    def test_ass_subtitles_and_zero_fonts(self):
        result, _ = run(mkvgen.build())
        self.assertEqual(result["subtitles"][0]["format"], "ass")
        self.assertEqual(result["attachments"], {"count": 0, "fonts": 0, "bytes": 0, "names": []})
        self.assertEqual(result["chapters"], {"present": False, "count": 0})

    def test_attachment_count_and_names_are_bounded(self):
        result, src = run(mkvgen.build(attach=[(f"f{i}.ttf", "font/ttf", 1) for i in range(600)]))
        self.assertEqual(result["attachments"]["count"], 500)
        self.assertEqual(len(result["attachments"]["names"]), 50)
        self.assertIn("attachments_truncated", result["warnings"])
        self.assertEqual(result["status"], "partial")

    def test_unknown_sizes(self):
        for kw in ({"unknown_segment": True}, {"unknown_cluster": True},
                   {"unknown_segment": True, "unknown_cluster": True}):
            with self.subTest(kw):
                result, _ = run(mkvgen.build(**kw))
                self.assertEqual(result["status"], "ok")
                self.assertEqual(result["encoder"]["library"], "x264")
                self.assertEqual(result["duration_s"], 1420.0)

    def test_tags_are_found_through_the_seekhead_past_the_cluster(self):
        data = mkvgen.build(tag_values={1001: {"BPS": "1234000"}}, attach=[("a.ttf", "font/ttf", 3 * MIB)])
        result, src = run(data)
        self.assertEqual(result["video"]["bitrate_source"], "tags")
        self.assertLess(result["bytes_read"], MIB)

    def test_no_seekhead_means_no_tags_but_still_ok(self):
        result, _ = run(mkvgen.build(tag_values={1001: {"BPS": "1234000"}}, with_seekhead=False))
        self.assertEqual(result["video"]["bitrate_source"], "size_over_duration")
        self.assertEqual(result["status"], "ok")

    def test_container_magic(self):
        mp4 = b"\x00\x00\x00\x18ftypisom\x00\x00\x02\x00" + bytes(64)
        result, _ = run(mp4)
        self.assertEqual((result["status"], result["container"]), ("unsupported_container", "mp4"))
        self.assertIsNone(result["video"])
        self.assertLessEqual(result["bytes_read"], 16)
        result, _ = run(b"Kura not a video file at all" * 4)
        self.assertEqual((result["status"], result["container"]), ("unsupported_container", "unknown"))
        for tiny in (b"", b"\x1a\x45\xdf", b"abc"):
            self.assertEqual(run(tiny)[0]["status"], "invalid")

    def test_headers_only_file_is_invalid_not_a_crash(self):
        result, _ = run(mkvgen.wrap(mkvgen.info()))
        self.assertEqual(result["status"], "invalid")
        self.assertEqual(result["duration_s"], 1420.0)
        result, _ = run(mkvgen.wrap(mkvgen.el(0xEC, b"\0" * 20)))
        self.assertEqual(result["status"], "invalid")
        self.assertIn("no_tracks", result["warnings"])


class Limits(unittest.TestCase):
    def base(self):
        return mkvgen.build(attach=[(f"Kura {n}.ttf", "font/ttf", 40) for n in "ABCDEF"], chapter_atoms=160,
                            tag_values={1001: {"BPS": "1000", "DURATION": "00:23:40.000000000"}},
                            subs=(("S_TEXT/ASS", "eng", "Kura"), ("S_TEXT/UTF8", "fil", None)),
                            audio_codecs=("A_AAC", "A_AC3"))

    def test_truncation_at_every_offset_never_raises(self):
        data = self.base()
        self.assertTrue(3000 < len(data) < 6000, len(data))
        start = time.monotonic()
        for k in range(len(data) + 1):
            for result in (probe(Source(data[:k]), k),                 # size says short
                           probe(Source(data[:k]), len(data))):       # size lies, reads come back short
                self.assertNotIn("internal_error", result["warnings"], k)
                self.assertIn(result["status"], ("ok", "partial", "invalid", "unsupported_container"))
                self.assertTrue(printable(result))
        self.assertLess(time.monotonic() - start, 20)
        self.assertEqual(probe(Source(data), len(data))["status"], "ok")

    def test_truncated_files_report_partial_when_something_was_read(self):
        data = self.base()
        cut = data.rindex(mkvgen.eid(0x1F43B675))                      # the Cluster, not the SeekHead entry
        result, _ = run(data[:cut + 40])
        self.assertEqual(result["status"], "partial")
        self.assertIn("truncated", result["warnings"])
        self.assertEqual(result["video"]["codec"], "h264")

    def test_random_mutations_never_raise_and_stay_fast(self):
        data = self.base()
        rng = random.Random(20261125)
        start = time.monotonic()
        for i in range(500):
            b = bytearray(data)
            for _ in range(rng.randint(1, 8)):
                at = rng.randrange(min(len(b), 300)) if rng.random() < 0.5 else rng.randrange(len(b))
                b[at] = rng.choice((0x00, 0x01, 0x7F, 0x80, 0xFE, 0xFF, rng.randrange(256)))
            roll = rng.random()
            if roll < 0.2:
                at = rng.randrange(len(b))
                del b[at:at + rng.randint(1, 200)]
            elif roll < 0.3:
                at = rng.randrange(len(b))
                b[at:at] = bytes(rng.randrange(256) for _ in range(rng.randint(1, 50)))
            elif roll < 0.4:
                del b[rng.randrange(len(b)):]
            src = Source(b)
            result = probe(src, src.size)
            self.assertNotIn("internal_error", result["warnings"], i)
            self.assertLessEqual(result["bytes_read"], 2 * MIB)
            self.assertLessEqual(src.largest, MIB)
            json.dumps(result)
            self.assertTrue(printable(result))
        self.assertLess(time.monotonic() - start, 20)

    def test_absurd_declared_sizes_cause_no_allocation_or_long_reads(self):
        giant = b"\x01\x00\xff\xff\xff\xff\xff\xfe"                      # 2**56 - 2, 8-byte size
        cases = {
            "segment": mkvgen.ebml() + mkvgen.eid(0x18538067) + giant + mkvgen.info(),
            "info": mkvgen.wrap(mkvgen.eid(0x1549A966) + giant),
            "tracks": mkvgen.wrap(mkvgen.info() + mkvgen.eid(0x1654AE6B) + giant),
            "cluster": mkvgen.wrap(mkvgen.info() + mkvgen.eid(0x1F43B675) + giant),
            "attachment": mkvgen.wrap(mkvgen.eid(0x1941A469) + giant),
            "skipped": mkvgen.wrap(mkvgen.eid(0xEC) + giant),
        }
        for name, data in cases.items():
            with self.subTest(name):
                result, src = run(data)
                self.assertNotIn("internal_error", result["warnings"])
                self.assertLessEqual(src.largest, 1 << 20)
                self.assertLess(result["bytes_read"], 1 << 16)
                self.assertIn(result["status"], ("partial", "invalid"))

    def test_depth_bomb_is_bounded(self):
        bomb = mkvgen.nested_chapters(3000)
        result, _ = run(mkvgen.build(extra_level1=bomb, with_seekhead=False))
        self.assertIn("depth_limit", result["warnings"])
        self.assertNotIn("internal_error", result["warnings"])
        nested = b""
        for _ in range(3000):
            nested = mkvgen.el(0xAE, mkvgen.uint(0xD7, 1) + nested)
        result, _ = run(mkvgen.wrap(mkvgen.info() + mkvgen.el(0x1654AE6B, nested)))
        self.assertNotIn("internal_error", result["warnings"])

    def test_chapter_bomb_reports_the_depth_limit(self):
        seg = mkvgen.info() + mkvgen.nested_chapters(50)
        result, _ = run(mkvgen.wrap(seg))
        self.assertIn("depth_limit", result["warnings"])
        self.assertEqual(result["status"], "partial")

    def test_element_limit(self):
        voids = mkvgen.el(0xEC) * (mkvprobe.MAX_ELEMENTS + 100)
        start = time.monotonic()
        result, _ = run(mkvgen.wrap(voids + mkvgen.info()))
        self.assertIn("element_limit", result["warnings"])
        self.assertLess(time.monotonic() - start, 5)

    def test_byte_budget_is_a_hard_cap(self):
        data = mkvgen.build()
        for cap in (0, 1, 16, 100, 300, 600):
            with self.subTest(cap):
                result, src = run(data, max_bytes=cap)
                self.assertLessEqual(src.total, cap)
                self.assertLessEqual(result["bytes_read"], cap)
                self.assertIn("budget_exhausted", result["warnings"])
                self.assertNotEqual(result["status"], "ok")
        self.assertEqual(run(data, max_bytes=2 * len(data))[0]["status"], "ok")   # headers are read twice

    def test_every_read_is_clamped_to_the_file(self):
        data = mkvgen.build()
        src = Source(data)
        probe(src, len(data))
        self.assertTrue(all(o >= 0 and o + n <= len(data) for o, n in src.reads), src.reads)

    def test_hostile_read_callbacks(self):
        data = mkvgen.build()
        bloated = probe(lambda o, n: data[o:o + n] + b"extra" * 100, len(data))     # more than asked
        self.assertEqual(bloated["status"], "ok")
        silent = probe(lambda o, n: b"", len(data))                                  # nothing ever comes back
        self.assertEqual(silent["status"], "invalid")
        self.assertNotIn("internal_error", silent["warnings"])

    def test_read_errors_propagate_and_are_not_swallowed(self):
        def broken(offset, n):
            raise OSError("boom")
        with self.assertRaises(OSError):
            probe(broken, 100)

    def test_argument_errors(self):
        for kw in ({"size": -1}, {"size": "x"}):
            with self.assertRaises(ValueError):
                probe(lambda o, n: b"", kw["size"])
        with self.assertRaises(ValueError):
            probe(lambda o, n: b"", 1, max_bytes=-1)

    def test_the_module_is_pure(self):
        for name in ("os", "sys", "socket", "subprocess", "open", "io"):
            self.assertFalse(hasattr(mkvprobe, name), name)
        self.assertEqual(mkvprobe.PROBE_VERSION, 1)


if __name__ == "__main__":
    unittest.main()
